/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function () {

    const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    $c.util.getComponent("ipt_secutizAdmInstCd").setValue(parentfm.secutiz_adm_inst_cd.value);
    $c.util.getComponent("ipt_secutizAdmInstNm").setValue(parentfm.secutiz_adm_inst_nm.value);
    $c.util.getComponent("ipt_secutizChrgNm").setValue(parentfm.secutiz_chrg_nm.value);
    $c.util.getComponent("ipt_secutizChrgTelNo").setValue(parentfm.secutiz_chrg_tel_no.value);
    const secutiz_chrg_tel_no = parentfm.secutiz_chrg_tel_no.value;
    if (secutiz_chrg_tel_no != null && secutiz_chrg_tel_no !== '') {
        const secutiz_chrg_tel_no_arr = secutiz_chrg_tel_no.split('-');
