/**
 * @method
 * @name checkInput
 * @description check Input 처리
 * @param {String} objCd objCd
 * @param {*} objName objName
 * @param {*} div div
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkInput = async function (objCd, objName, div) {
    fm = (document.InputForm || { elements: [] });
    const preDiv = parseInt(div) - 1;
    if ($c.util.getComponent("fm." + objName + preDiv).value === '') {
        await $c.win.alert(preDiv + "차 기관 입력이 누락되었습니다.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    } else {
        window_iss_inst_cd(objCd + div, objName + div);
    }
};

/**
 * @method
 * @name checkSelect
 * @description check Select 처리
 * @param {String} objCd objCd
 * @param {*} div div
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSelect = async function (objCd, div) {
    fm = (document.InputForm || { elements: [] });
    const preDiv = parseInt(div) - 1;
    if ($c.util.getComponent("fm." + objCd + preDiv).value === '') {
        await $c.win.alert(preDiv + "차 유형 입력이 누락되었습니다.");
        $c.util.getComponent("fm." + objCd + div).setValue('');
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
};

/**
 * @method
 * @name inst_del
 * @description inst del 처리
 * @param {*} id id
 * @param {*} nm nm
 * @returns {void}
